\set ON_ERROR_STOP 1
begin;
insert into weather_cells (id, lat_idx, lon_idx, ele_band, latitude, longitude, next_refresh_at, nearest_need_at, last_demand_at, attempts, created_at, updated_at) values (901, 1, 1, null, 0, 0, now(), now()+interval '1 day', now(), 0, now(), now()) on conflict (lat_idx, lon_idx, ele_band) do update set last_demand_at = excluded.last_demand_at, nearest_need_at = excluded.nearest_need_at, next_refresh_at = case when weather_cells.attempts > 0 then weather_cells.next_refresh_at when weather_cells.fetched_at is null then excluded.next_refresh_at else weather_cells.fetched_at + make_interval(secs => 3600) end, updated_at = excluded.updated_at;
select pg_sleep(2);
insert into weather_cells (id, lat_idx, lon_idx, ele_band, latitude, longitude, next_refresh_at, nearest_need_at, last_demand_at, attempts, created_at, updated_at) values (902, 2, 2, null, 0, 0, now(), now()+interval '1 day', now(), 0, now(), now()) on conflict (lat_idx, lon_idx, ele_band) do update set last_demand_at = excluded.last_demand_at, nearest_need_at = excluded.nearest_need_at, next_refresh_at = case when weather_cells.attempts > 0 then weather_cells.next_refresh_at when weather_cells.fetched_at is null then excluded.next_refresh_at else weather_cells.fetched_at + make_interval(secs => 3600) end, updated_at = excluded.updated_at;
commit; select 'planner committed';
